61	/**
62	 * Tools that can cause a full-page navigation (explicitly or implicitly).
63	 *
64	 * When any of these completes successfully, the current page DOM is replaced
65	 * and the injected automation overlay is lost. BrowserManager re-injects the
66	 * overlay after every successful call to one of these tools.
67	 *
68	 * Note: chrome-devtools-mcp is a pure request/response server and emits no
69	 * MCP notifications, so listening for page-load events via the protocol is
70	 * not possible. Intercepting at callTool() is the equivalent mechanism.
71	 */
72	const POTENTIALLY_NAVIGATING_TOOLS = new Set([
73	  'click', // clicking a link navigates
74	  'click_at', // coordinate click can also follow a link
75	  'navigate_page',
76	  'new_page',
77	  'select_page', // switching pages can lose the overlay
78	  'press_key', // Enter on a focused link/form triggers navigation
79	  'handle_dialog', // confirming beforeunload can trigger navigation
